Below is a **complete, minimal TCP “command” server** written in plain C (POSIX sockets).  
It

* creates a listening socket,
* accepts **one** client connection,
* reads a line‑oriented command from the client,
* echoes the command back prefixed with `"OK: "` (you can replace this with any real command handling you need),
* closes the connection and exits.

The program is deliberately tiny – only the essential system calls and a few safety checks are included – so you can copy‑paste it, compile it, and start playing with it right away.

---

## 1. Source code (`tcp_cmd_server.c`)

```c
/*
 * Minimal TCP command server – handles a single client.
 *
 * Build:   gcc -Wall -Wextra -O2 -o tcp_cmd_server tcp_cmd_server.c
 *
 * Run:     ./tcp_cmd_server <port>
 *
 * The server accepts one client, reads newline‑terminated commands,
 * replies with "OK: <command>\n", then waits for the next command.
 * When the client closes the connection the server exits.
 *
 * This is deliberately minimal – error handling is simple and
 * the code is kept to a few hundred lines.
 */

#define _POSIX_C_SOURCE 200112L   /* for getaddrinfo() etc. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <ctype.h>

#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>

/* -------------------------------------------------------------
 * Helper: print a human‑readable error and exit.
 * ------------------------------------------------------------- */
static void die(const char *msg)
{
    perror(msg);
    exit(EXIT_FAILURE);
}

/* -------------------------------------------------------------
 * Helper: read a line (up to \n) from a socket.
 * Returns the number of bytes placed in buf (excluding the '\0').
 * On EOF or error returns -1.
 * ------------------------------------------------------------- */
static ssize_t read_line(int fd, char *buf, size_t maxlen)
{
    size_t n = 0;
    char c;

    while (n + 1 < maxlen) {
        ssize_t r = recv(fd, &c, 1, 0);
        if (r == 0)               /* client closed connection */
            return -1;
        if (r < 0) {
            if (errno == EINTR)   /* interrupted, retry */
                continue;
            return -1;
        }

        buf[n++] = c;
        if (c == '\n')
            break;
    }
    buf[n] = '\0';
    return (ssize_t)n;
}

/* -------------------------------------------------------------
 * Main
 * ------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *port = argv[1];
    int listen_fd = -1, client_fd = -1;
    struct addrinfo hints, *res, *rp;

    /* ---- 1. Resolve the local address we want to bind to ---- */
    memset(&hints, 0, sizeof(hints));
    hints.ai_family   = AF_UNSPEC;      /* IPv4 or IPv6 */
    hints.ai_socktype = SOCK_STREAM;    /* TCP */
    hints.ai_flags    = AI_PASSIVE;     /* for bind() */

    int s = getaddrinfo(NULL, port, &hints, &res);
    if (s != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(s));
        exit(EXIT_FAILURE);
    }

    /* ---- 2. Create socket, set SO_REUSEADDR, bind, listen ---- */
    for (rp = res; rp != NULL; rp = rp->ai_next) {
        listen_fd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (listen_fd == -1)
            continue;   /* try next address */

        int opt = 1;
        if (setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0)
            die("setsockopt");

        if (bind(listen_fd, rp->ai_addr, rp->ai_addrlen) == 0)
            break;        /* success */

        close(listen_fd);
        listen_fd = -1;
    }

    freeaddrinfo(res);

    if (listen_fd == -1)
        die("Could not bind to any address");

    if (listen(listen_fd, 1) < 0)   /* backlog = 1 is enough for a single client */
        die("listen");

    printf("Listening on port %s …\n", port);

    /* ---- 3. Accept a single client ---- */
    struct sockaddr_storage client_addr;
    socklen_t client_len = sizeof(client_addr);
    client_fd = accept(listen_fd,
                        (struct sockaddr *)&client_addr,
                        &client_len);
    if (client_fd < 0)
        die("accept");

    /* Print client address (nice to have) */
    char host[NI_MAXHOST], serv[NI_MAXSERV];
    if (getnameinfo((struct sockaddr *)&client_addr, client_len,
                    host, sizeof(host), serv, sizeof(serv),
                    NI_NUMERICHOST | NI_NUMERICSERV) == 0) {
        printf("Accepted connection from %s:%s\n", host, serv);
    }

    /* ---- 4. Command loop ------------------------------------------------ */
    const size_t BUF_SIZE = 1024;
    char buf[BUF_SIZE];

    while (1) {
        ssize_t n = read_line(client_fd, buf, BUF_SIZE);
        if (n <= 0) {
            printf("Client disconnected.\n");
            break;
        }

        /* Strip trailing newline / carriage‑return for nicer output */
        size_t len = strlen(buf);
        while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r')) {
            buf[--len] = '\0';
        }

        printf("Received command: \"%s\"\n", buf);

        /* ---- 4a. Very simple command handling --------------------------- */
        /* Replace this block with whatever you actually want to do. */
        char reply[BUF_SIZE];
        int rlen = snprintf(reply, sizeof(reply), "OK: %s\n", buf);
        if (rlen < 0 || (size_t)rlen >= sizeof(reply))
            rlen = sizeof(reply) - 1;   /* truncate if something went wrong */

        /* ---- 4b. Send reply ------------------------------------------------ */
        ssize_t sent = 0;
        while (sent < rlen) {
            ssize_t w = send(client_fd, reply + sent, rlen - sent, 0);
            if (w < 0) {
                if (errno == EINTR) continue;
                perror("send");
                break;
            }
            sent += w;
        }
    }

    /* ---- 5. Clean up ------------------------------------------------------ */
    close(client_fd);
    close(listen_fd);
    printf("Server terminated.\n");
    return 0;
}
```

